  // src/search.js
  var TIPS = ["Scouting the land", "Matching by power", "Counting the walls", "Weighing the vaults", "Reading the banners"];
  var sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  async function findOpponent(econ2, { opts = {}, minMs = 1200, onProgress = () => {
  }, ctl = { cancelled: false } } = {}) {
    const t0 = performance.now();
    let res = null, tries = 0;
    let f = 0, cap = 0.6, rate2 = 0.2, tipI = 0, tipT = 0, found = false;
    const target = (to, secs) => {
      cap = Math.max(f, Math.min(1, to));
      rate2 = Math.max(0.02, (cap - f) / Math.max(0.2, secs));
    };
    const tick = setInterval(() => {
      const dt = 0.08;
      if (f < cap) f = Math.min(cap, f + rate2 * dt);
      tipT += dt;
      if (tipT > 1.1 && !found) {
        tipT = 0;
        tipI = (tipI + 1) % TIPS.length;
      }
      onProgress(f, found ? "Opponent found" : TIPS[tipI] + "\u2026");
    }, 80);
    const nap = async (ms) => {
      const e = performance.now() + ms;
      while (!ctl.cancelled && performance.now() < e) await sleep(100);
    };
    try {
      target(0.6, 3);
      while (!ctl.cancelled && tries++ < 40) {
        let j = null;
        try {
          j = await econ2.scout(opts);
        } catch (e) {
          j = { ok: false, why: "offline" };
        }
        if (j && j.ok && j.target) {
          res = j;
          break;
        }
        if (j && j.why === "slow") {
          const w = Math.max(0.8, Math.min(30, +j.wait || 1.5));
          target(0.94, w);
          await nap(w * 1e3 + 120);
          continue;
        }
        res = j || { ok: false, why: "bad" };
        break;
      }
      if (ctl.cancelled) return { ok: false, why: "cancel" };
      if (res && res.ok && res.target) {
        const rest = minMs - (performance.now() - t0);
        if (rest > 0) {
          target(0.92, rest / 1e3);
          await sleep(rest);
        }
        if (ctl.cancelled) return { ok: false, why: "cancel" };
        found = true;
        target(1, 0.35);
        await sleep(420);
        if (ctl.cancelled) return { ok: false, why: "cancel" };
        return { ok: true, target: res.target, raw: res };
      }
      return { ok: false, why: res && res.why || "bad" };
    } finally {
      clearInterval(tick);
    }
  }

