        if (v > f) f = v;
        fill.style.width = (f * 100).toFixed(1) + "%";
        const p = Math.round(f * 100) + "%";
        if (pcEl.textContent !== p) pcEl.textContent = p;
        if (txt && subEl.textContent !== txt) subEl.textContent = txt;
        return api;
