      return `<div class="bsh-st3">${stat("vault", fmtN(c.econ.st.gems[g] || 0), "Stored")}${stat("box", fmtN(c.econ.st.vault[g] || 0), "Capacity")}${stat("mine", fmtN(M.ready), "In the mine")}</div>${nextLine(id, c)}`;
